const body = $json;
const executions = body.data || [];

const total = executions.length;
const failed = executions.filter(e => e.status === 'error' || e.status === 'failed');
const success_rate = total ? Math.round(((total - failed.length) / total) * 1000) / 10 : 100;

const durations = executions
  .filter(e => e.startedAt && e.stoppedAt)
  .map(e => (new Date(e.stoppedAt).getTime() - new Date(e.startedAt).getTime()));
const avg_duration_ms = durations.length ? Math.round(durations.reduce((a, b) => a + b, 0) / durations.length) : 0;

const errorTypes = [...new Set(failed.map(e => e.status))];
const latestFailure = failed[0] || null;

// Health score formula: successRate weighted 60%, duration weighted 40% (penalty above 3s)
const duration_score = Math.max(0, 100 - Math.max(0, avg_duration_ms - 3000) / 100);
const overall_health_score = Math.round((success_rate * 0.6) + (duration_score * 0.4));

return [{
  json: {
    total_executions: total,
    success_rate,
    avg_duration_ms,
    error_count: failed.length,
    error_types: errorTypes,
    latest_failure_id: latestFailure ? latestFailure.id : null,
    latest_failure_workflow: latestFailure ? (latestFailure.workflowId || 'unknown') : null,
    overall_health_score
  }
}];
